const barChart = `<figure class="bar-chart"><figcaption>Bar chart: sampled complaint audit, shown as share of 80 negative public reviews and complaint examples.</figcaption>${reviewThemes.map(([label, value, color, count]) => `<div class="bar-row"><span>${label}</span><div><i style="width:${value}%;background:${color}"></i></div><strong>${value}%</strong><em>${count}</em></div>`).join("")}</figure>`;
const evidenceSources = `<p class="muted">Evidence base: sampled public-review audit of negative Ancestry, MyHeritage, MacFamilyTree and Family Tree Maker complaint examples found in App Store, ConsumerAffairs, BBB, Trustpilot, Reddit and genealogy-review sources; Dupple's 377-tool pricing-transparency count; Steal What Works' 84-tool survey-software pricing study; Chili Piper's B2B buying-journey report; and genealogy/family-history scholarship on identity, belonging and wellbeing.</p>`;
const foundingStory = `${heading("Founding Story", "Why KinForge exists", "KinForge began from a simple frustration: relationship tools were either too narrow for creative worlds, too expensive for growing users, too hard to explain, or too separated from reports, sources and real-life context.")}<section class="wrap section beta-layout"><div class="prose"><h2>The idea</h2><p>KinForge is built for people who need to understand complicated human connections: families, cases, character worlds, historical networks, campaigns, books, classrooms and care contexts. The app is not only for genealogy. It is also for social workers, writers, authors, illustrators, historians, roleplayers, RPG players, educators and anyone who needs relationship clarity.</p><p>The product direction came from looking at genealogy apps, family-tree sites, creator tools, support needs, payment models and public user complaints. The goal is to keep the best parts: rich charts, reports, libraries, exports, account sync, role-specific pages and clear pricing, while making the confusing parts easier to understand.</p><h2>What the complaint audit showed</h2><p>The complaint chart groups a sampled set of 80 public negative review and complaint examples. Pricing, renewal, cancellation and paid add-ons were the largest theme, followed by sync/export worries, support problems, usability/performance issues and missing workflows for creators, care contexts, privacy and nontraditional relationships.</p></div>${reviewThemeChart}</section><section class="wrap section"><h2>Research charts</h2><p class="lead">These charts separate two kinds of evidence: public-review complaint themes, and published software-pricing research about how often tools hide or gate pricing.</p><div class="chart-grid">${donutChart}${barChart}</div>${evidenceSources}</section><section class="band"><div class="wrap prose"><h2>Why the interface had to be better</h2><p>KinForge was also shaped by design experience. As former UI and UX designers and former design students, we found that some genealogy and relationship-mapping services can feel crowded, slow, difficult to understand, difficult to navigate, or not accessible enough for the people who most need clarity.</p><p>That matters because relationship work is already emotionally and mentally demanding. A user should not have to fight the interface before they can understand a family line, a case context, a book series, a campaign history, or a character relationship.</p><p>This is why accessibility is part of the product idea: clearer layouts, readable reports, plain-language explanations, disability-aware records, low-vision and dyslexia-friendly controls, language support, privacy choices and a calmer interface. Creators, researchers, social workers, disabled users and everyday family historians should be able to come in, understand what they are seeing, and get what they need without being shut out by confusing UI.</p></div></section><section class="band"><div class="wrap"><h2>Why genealogy matters</h2><p class="lead">Genealogy is not just a hobby list of names. It can support identity, belonging, wellbeing, care context, medical-family-history context, historical understanding, evidence literacy and stronger storytelling.</p><div class="feature-columns">${genealogyEvidence.map(([title, text]) => `<article><h3>${title}</h3><p>${text}</p></article>`).join("")}</div><p>For social workers and care teams, relationship mapping can make context visible. For writers, authors, roleplayers and RPG players, family and social networks make character motives, inheritance, secrets, loyalties and worldbuilding easier to keep consistent. For historians and genealogists, it keeps evidence, uncertainty and relationships connected instead of scattered.</p></div></section><section class="band"><div class="wrap"><h2>Shareable infographic</h2><p class="lead">Press and social-media style images explain KinForge's mission, the sampled complaint pie chart, and the research-backed reasons relationship mapping matters.</p><div class="infographic-grid"><figure class="infographic"><img src="/website/infographics/kinforge-research-story-landscape.png" alt="Landscape KinForge research infographic with evidence-backed complaint chart and genealogy importance points"><figcaption>Landscape PNG. Also available as JPG, HEIC and PDF.</figcaption></figure><figure class="infographic"><img src="/website/infographics/kinforge-research-story-portrait.png" alt="Portrait KinForge research infographic with evidence-backed complaint chart and genealogy importance points"><figcaption>Portrait PNG. Also available as JPG, HEIC and PDF.</figcaption></figure></div><div class="actions left"><a class="button" href="/website/infographics/kinforge-research-story-landscape.pdf">Download landscape PDF</a><a class="button secondary" href="/website/infographics/kinforge-research-story-portrait.pdf">Download portrait PDF</a></div></div></section><section class="wrap section prose"><h2>How this shaped the app</h2><div class="feature-columns"><article><h3>Clearer pricing</h3><p>Personal plans, Business Suite plans, role discounts, taxes and quote requests are explained instead of hidden behind one vague contact button.</p></article><article><h3>More than family trees</h3><p>The app supports family history, genograms, fictional casts, RPG campaigns, social-work context, education projects and research networks.</p></article><article><h3>Portable work</h3><p>Reports, exports, backups, downloads and role-specific pages keep the user in control of their own work and expectations.</p></article></div><h2>For public, paid, free and Special Access editions</h2><p>The founding story applies to every KinForge edition. Free users can explore the demo and basic workflows, paid users can grow into larger libraries and support, Special Access users can redeem owner-provided codes, and business users can request quotes for seats, procurement and education use.</p><div class="actions left"><a class="button" href="/website/pricing/">See plans</a><a class="button secondary" href="/website/discounts/">See role discounts</a></div></section>`;
const rolePageContent = (page: typeof rolePages[number]) => `${heading("Role-based KinForge", page.title, page.description)}<section class="wrap section beta-layout"><div class="prose"><h2>Built for ${page.audience}</h2><p>KinForge gives this group a focused path through the same relationship studio: charts, people, reports, libraries, sources, exports and collaboration, with language that matches how the work is actually used.</p><ul>${page.uses.map(use => `<li>${use}</li>`).join("")}</ul><p><strong>Discount path:</strong> use <code>${page.code}</code> during checkout or include it in a quote request.</p><p><a href="/website/founding-story/">Read the founding story and research-theme chart</a>.</p></div><section class="signup-panel"><h2>Start here</h2><p>Try the web app, then choose a personal plan or request a Business Suite quote if you are buying for a group.</p><a class="button" href="/website/pricing/">See plans</a><a class="button secondary" href="/website/discounts/#quote">Request a quote</a></section></section><section class="band"><div class="wrap"><h2>Why this page exists</h2><p>Software websites often create separate pages for educators, creators, teams or industries so each visitor can quickly see whether the product fits them. This page keeps that same idea focused on KinForge's discounted roles.</p></div></section>`;
const pricing = `${heading("Plans & pricing", "Choose the KinForge plan that fits your work", "Transparent subscription tiers for family history, social work, books, RPG campaigns, historical research, character worlds and serious genealogy projects.")}<section class="wrap section"><h2>Personal plans</h2><p class="lead">Personal plans are for one account. Use them for individual family history, writing, illustration, roleplay, RPG campaigns, research, study, and personal case planning.</p><div class="pricing-grid">${plans.map(plan => `<article class="price-card"><h2>${plan.name}</h2><p class="price"><strong>${plan.price}</strong><span>${plan.cadence}</span></p><p>${plan.summary}</p><ul>${plan.features.map(feature => `<li>${feature}</li>`).join("")}</ul><a class="button secondary" href="${plan.name === "Beta Program" ? "/website/beta/" : "/app"}">${plan.name === "Free" ? "Start free" : plan.name === "Beta Program" ? "Join beta interest" : "Create account"}</a></article>`).join("")}</div></section><section class="band"><div class="wrap"><h2>Business Suite</h2><p>Business Suite plans support multiple seats for organisations, student groups, agencies, studios, writing teams, research teams, and classrooms. Every Business Suite tier can be paid weekly, monthly, or annually, and every tier can request a quote for seat count, contract length, modules, onboarding, taxes, procurement paperwork, or education/nonprofit pricing.</p><div class="business-grid">${businessPlans.map(plan => `<article><h3>${plan.name}</h3><p><strong>${plan.seats}</strong></p><p>${plan.summary}</p><dl><dt>Weekly</dt><dd>${plan.weekly}</dd><dt>Monthly</dt><dd>${plan.monthly}</dd><dt>Annual</dt><dd>${plan.annual}</dd></dl><a class="button secondary" href="/website/discounts/#quote">Request a quote</a></article>`).join("")}</div></div></section><section class="wrap section prose"><h2>Discounts, taxes and currency conversion</h2><p>Base pricing is in Singapore dollars (SGD). Stripe Checkout and Stripe Billing handle paid checkout, subscription renewal, invoices, coupons, promotion codes, billing history and supported local-currency presentation where available. The final amount can change because of exchange rates, card issuer fees, GST, VAT, sales tax, digital-services tax, withholding rules, or other taxes required by the customer's location.</p><p>Special discount rates include creator, education, care, roleplay, accessibility and hardship/subsidised-quote paths. ACCESS15 is for disabled users and users with mental-health, neurodevelopmental, learning, chronic-health, intellectual-disability, disorder-related or other condition-related access needs. Professional diagnosis proof, disability documentation, or a short self-diagnosis/self-assessment statement can be accepted; only the minimum proof should be requested and sensitive details should be treated privately.</p><p>Taxes are calculated or collected where the payment system is configured to do so. If Stripe Tax or local tax registration is not active for a region yet, checkout may show that tax is not currently collected by KinForge for that region. Customers remain responsible for any taxes their local law requires.</p><p><a href="/website/discounts/">Open discounts and quote requests</a> to see the role-based codes, request a quote, or ask about an organisation purchase.</p><h2>Billing notes</h2><p>Subscriptions renew automatically until cancelled. Paid plans are for account access and hosted features; desktop installers can still require the correct account permissions. Refunds, trials, invoices, coupons, subscription changes, payment history and billing portal access are handled through Stripe once the Stripe account keys, product prices, webhook secret and tax settings are connected. Owner revenue in KinForge is populated from signed Stripe webhook events plus any manual owner entries.</p><div class="actions left"><a class="button" href="/app">Create or sign in</a><a class="button secondary" href="/website/support/">Ask a billing question</a></div></section>`;
const discountPage = `${heading("Discounts & quote requests", "Special rates for creators, care teams, students and organisations", "Tell KinForge what role you belong to, choose a personal or business plan, and request a quote when pricing depends on seats, contract length, onboarding, modules, taxes or procurement paperwork.")}${roleChooser}<section class="band"><div class="wrap"><h2>Special discount roles</h2><div class="discount-grid">${discounts.map(([code, rate, who]) => `<article><strong>${code}</strong><span>${rate}</span><p>${who}</p></article>`).join("")}</div><p class="muted">Only one discount code can be used at a time unless Dreams of Serene Landscapes approves otherwise. Eligibility may be reviewed before a discount is applied. Accessibility discount proof may be a professional diagnosis, disability or access-needs documentation, or a self-diagnosis/self-assessment statement. Customers should not send more sensitive detail than necessary.</p><p class="muted"><strong>Subsidised quote scheme:</strong> if the normal prices are not affordable, a personal user or organisation can request a subsidised quote, suggest a reasonable cost, and explain why support is needed. Approval is reviewed case by case and is not automatic.</p></div></section><section class="wrap section"><h2>Role pages</h2><p class="lead">Each discounted role has its own page, like software sites that create separate pages for educators, creators, teams, or industries.</p><div class="business-grid">${rolePages.map(page => `<article><h3>${page.title.replace("KinForge for ", "")}</h3><p>${page.description}</p><p><strong>${page.code}</strong></p><a class="button secondary" href="${page.path}">Open page</a></article>`).join("")}</div></section><section class="wrap section"><h2>Business Suite seat pricing</h2><p class="lead">Use Business Suite when an organisation, school, studio, social-work team, writing group, RPG group, or research team is buying access for multiple people.</p><div class="business-grid">${businessPlans.map(plan => `<article><h3>${plan.name}</h3><p><strong>${plan.seats}</strong></p><p>${plan.summary}</p><dl><dt>Weekly</dt><dd>${plan.weekly}</dd><dt>Monthly</dt><dd>${plan.monthly}</dd><dt>Annual</dt><dd>${plan.annual}</dd></dl></article>`).join("")}</div></section><section class="wrap section beta-layout" id="quote"><div class="prose"><h2>Request a quote</h2><p>A quote request is for pricing that needs review before checkout: larger seat counts, schools or student cohorts, annual invoices, business procurement, tax exemption, migration help, onboarding, custom modules, sensitive-data requirements, a buying timeline, or a subsidised personal or business price because the normal price is not affordable.</p><p>Include the plan, number of seats, preferred weekly/monthly/annual payment, contract length, country, organisation type, tax or exemption notes, onboarding or migration needs, timeline, any role discount code that may apply, and your suggested affordable cost if requesting a subsidy.</p><p>No payment is taken just because you request a quote. The request is stored for KinForge Support so Dreams of Serene Landscapes can review it and reply.</p></div><section class="signup-panel"><h2>Quote request details</h2><p>Open the form and choose <strong>Business quote request</strong>. The request is stored for KinForge Support so Dreams of Serene Landscapes can review it and reply before sending checkout, invoice, discount or quote details.</p><ul><li>Plan and add-ons</li><li>Seat count and contract length</li><li>Billing cadence</li><li>Country, tax and procurement details</li><li>Timeline, onboarding and migration needs</li></ul><a class="button" href="/website/support/#public-support">Open quote form</a></section></section>`;
const releases = `${heading("Releases & updates", `KinForge ${release.version}`, "The current desktop preview for Apple Silicon, Intel and Windows. Your library is separate from your installed app version.")}<section class="wrap section prose"><article><p class="eyebrow">Current desktop release</p><h2>Version ${release.version}</h2><ul><li>Top-bar app language selection, separate from tree language.</li><li>Owner support and payment-monitoring updates stay separate from the public customer pages.</li><li>Apple Silicon, Intel and Windows packages.</li></ul><a class="button" href="/downloads">Download ${release.version}</a></article><article><p class="eyebrow">Website update</p><h2>A home for KinForge</h2><p>Use-case pages for social workers, writers, genealogists, historians, roleplayers, RPG players and relationship-rich projects, plus tutorial videos, official app downloads, beta interest registration and public export credit guidance.</p><p>The public pages explain the app for customers while owner-only operations remain behind the signed-in owner workspace.</p></article><h2>Updating an installation</h2><p>Use the in-app Update Agent to check published packages. An already-current version should not need reinstalling. Export a backup before installing a beta or making major changes.</p><h2>Try the beta safely</h2><p>The available installers include the separate guest demo. Beta interest uses a KinForge account and does not collect payment on this website.</p></section>`;
const privacy = `${heading("Privacy & beta safety", "Your work stays yours", "Use fictional demo data to explore. Treat real family, medical and identity records with care.")}<section class="wrap section prose"><h2>Accounts and libraries</h2><p>KinForge uses separate email-and-password accounts. Signing in identifies your cloud library. Sharing is an explicit choice; the guest demo is not a shared-account login.</p><h2>Account terms</h2><p>New accounts must agree to KinForge copyright, export and download terms. Normal exports keep the KinForge copyright and credit. Copyright-free permission is reviewed through support before account creation or use.</p><h2>Interest registration</h2><p>Your beta interest and registration time are stored with your account. No card data is collected here. Withdraw your interest on the beta page while signed in.</p><h2>Copyright-free permission proof</h2><p>Only approved close or special people may receive permission to make a copyright-free version and place their own copyright on their books. They must provide real, non-AI proof through support, such as photos together or other digital or physical records. If approved, they should still credit Dreams of Serene Landscapes when asked.</p><h2>Beta safety</h2><p>Experimental releases may fail. Use a sandbox, keep independent backups and test before changing important work. Zero data loss cannot be guaranteed.</p><h2>Public website</h2><p>Public pages do not expose your trees or account contents. This update adds no advertising trackers or analytics cookies. Hosting providers may still process technical logs.</p><h2>Questions</h2><p><a href="/website/support/">Open the permission and support form</a>.</p></section>`;
const privacyPolicy = `${heading("Privacy Policy", "How KinForge handles information", `Effective ${LEGAL_EFFECTIVE_DATE}. This policy applies to the app, website, beta, accounts, support forms, exports and downloads.`)}<section class="wrap section prose">${legalSections(PRIVACY_POLICY_SECTIONS)}<p><a href="/website/support/">Contact support about privacy</a>.</p></section>`;
const termsConditions = `${heading("Terms & Conditions", "Rules for using KinForge", `Effective ${LEGAL_EFFECTIVE_DATE}. These terms apply before using the app, creating an account, trying the demo, checking updates, exporting, or downloading files.`)}<section class="wrap section prose">${legalSections(TERMS_CONDITIONS_SECTIONS)}<p><a href="/website/support/">Request permission or ask a question</a>.</p></section>`;
const support = `${heading("Support & permission", "Ask before a copyright-free version", "Use this form for support, beta questions, quotes, or a copyright-free permission request before creating an account.")}<section class="wrap section beta-layout"><div>${exportTerms}<h2>Proof requirements</h2><p>For copyright-free permission, explain why you are close to Dreams of Serene Landscapes and provide real proof. Proof can include non-AI photos together, a link to shared records, or a description of physical or digital evidence you can provide. Do not upload private identity documents into this public form.</p><p>For business quotes or subsidised quote requests, include the plan, seats, contract length, preferred weekly/monthly/annual payment, country, organisation type, tax or exemption notes, procurement needs, onboarding or migration needs, timeline, any discount role or code, the cost you can reasonably afford, and why support is needed. For ACCESS15, users may provide a professional diagnosis, disability documentation, or a brief self-diagnosis/self-assessment statement without sharing unnecessary medical detail.</p><p>Approval is not automatic. If permission is not granted, exported or downloaded KinForge files keep the KinForge copyright and credit.</p></div><section class="signup-panel" aria-labelledby="support-title"><h2 id="support-title">Support form</h2><form id="public-support"><label>Name<input name="name" autocomplete="name" maxlength="100"></label><label>Email for replies<input name="email" type="email" autocomplete="email" required></label><label>Request type<select name="type"><option>Copyright-free permission request</option><option>Business quote request</option><option>Special discount eligibility question</option><option>Accessibility discount request</option><option>Subsidised quote request</option><option>Support request</option><option>Account or login help</option><option>Download question</option><option>Bug report</option></select></label><label>Subject<input name="subject" maxlength="160" value="Copyright-free permission request"></label><label>Proof, role, quote, or organisation details<textarea name="proof" rows="5" placeholder="For quotes, include plan, seats, billing cadence, country, timeline, discount code, and suggested affordable cost if requesting subsidy. For ACCESS15, use minimum proof." required></textarea></label><label>Message<textarea name="message" rows="6" placeholder="Explain what you need and how KinForge will be used." required></textarea></label><label class="check"><input name="permissionToReply" type="checkbox" checked>Allow support to reply to this email</label><button type="submit">Send request</button></form><p id="support-result" role="status" aria-live="polite"></p></section></section>`;
const pages: Record<string, [string, string, string]> = {
  "/website/": ["KinForge Genealogy Studio", "Relationship mapping, family tree, genogram and character planning software for social workers, writers, genealogists, historians, roleplayers and RPG players.", home],
  "/website/app/": ["Official KinForge app", "Official KinForge Genealogy Studio app page with browser, Mac and Windows download links for social workers, writers, genealogists, historians, roleplayers and RPG players.", officialApp],
  "/website/features/": ["Relationship maps, genograms and family trees", "Plan family relationships, social-work genograms, character networks, history projects and RPG campaigns with KinForge.", features],
  "/website/pricing/": ["Plans and pricing", "KinForge pricing plans, beta pricing, discount codes, tax notes and subscription information in SGD with local currency support where available.", pricing],
  "/website/discounts/": ["Discounts and quote requests", "KinForge special discount roles, personal pricing, Business Suite seat pricing, and quote requests for organisations and groups.", discountPage],
  "/website/founding-story/": ["Founding Story", "The KinForge founding story with a research-theme pie chart about competitor review complaints and app design lessons.", foundingStory],
  ...Object.fromEntries(rolePages.map(page => [page.path, [page.title, page.description, rolePageContent(page)]] as const)),
  "/website/tutorials/": ["Video tutorials", "Captioned KinForge tutorials and downloadable MP4 walkthroughs for the demo, person profiles and reports.", tutorialPage],
  "/website/getting-started/": ["Getting started", "Try the demo, create an account, organize books and start a relationship map in KinForge.", gettingStarted],
  "/website/beta/": ["Join the beta program", "Register your interest in KinForge beta releases with your account. Stripe handles paid beta checkout when billing is enabled; no payment is taken during interest registration.", beta],
  "/website/support/": ["Support and permission", "Request KinForge support or copyright-free permission with real non-AI proof before creating an account.", support],
  "/website/releases/": ["Releases and updates", "KinForge release information and downloads for Apple Silicon, Intel and Windows.", releases],
  "/website/privacy/": ["Privacy and beta safety", "KinForge accounts, beta interest registration, public export credit and safe testing with backups.", privacy],
  "/website/privacy-policy/": ["Privacy Policy", "KinForge Privacy Policy for app accounts, support, beta, exports, downloads and relationship-map libraries.", privacyPolicy],
  "/website/terms/": ["Terms and Conditions", "KinForge Terms and Conditions covering app use, copyright, exports, downloads, beta, accounts and permission requests.", termsConditions]
};
export const publicPaths = [...Object.keys(pages), "/downloads"];
export function publicWebsiteRoutes(request: Request): Response | null {
  const path = new URL(request.url).pathname;
  if (!["GET", "HEAD"].includes(request.method)) return null;
  const canonical = path === "/website/index.html" || path === "/website" ? "/website/" : `${path}/`;
  if (!pages[path] && pages[canonical]) return new Response(null, { status: 308, headers: { Location: canonical } });
  if (pages[path]) return websiteResponse(request, path, ...pages[path]);
  if (path === "/robots.txt") return new Response(request.method === "HEAD" ? null : `User-agent: *\nAllow: /website/\nAllow: /downloads\nDisallow: /api/\nSitemap: ${siteOrigin}/sitemap.xml\n`, { headers: { "Content-Type": "text/plain; charset=utf-8" } });
  if (path === "/sitemap.xml") return new Response(request.method === "HEAD" ? null : `<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${publicPaths.map(p => `<url><loc>${siteOrigin}${p}</loc></url>`).join("")}</urlset>`, { headers: { "Content-Type": "application/xml; charset=utf-8" } });
  return null;
}
